  if (skyCv && skyKey === key) return skyCv;
  if (!skyCv) skyCv = document.createElement("canvas");
  skyCv.width = W; skyCv.height = GROUND + 2;
  skyKey = key;
  const g = skyCv.getContext("2d")!;
  const hz = hazeLuz();
