  const sunC = function (a, b) { return rgbS(luzDoDia(mixA(a, b, h))); };
  // In GO FAST you are looking at it through the air you are making: the corona swells and
  // goes orange while the disc itself dulls, which is what a sun in smoke actually does.
  const gl = mixA([255, 236, 150], [255, 170, 74], rq), gl2 = mixA([255, 240, 168], [255, 186, 92], rq);
  g.globalAlpha = (1 - noite) * (0.16 + 0.22 * h + 0.20 * rq); disco(rgbS(mixA([226, 220, 204], gl, h)), r + 5 + Math.round(rq * 6));
  g.globalAlpha = (1 - noite) * (0.34 + 0.30 * h + 0.16 * rq); disco(rgbS(mixA([230, 224, 208], gl2, h)), r + 2 + Math.round(rq * 3));
  g.globalAlpha = 1 - noite * 0.94;
