  fo: "#3e4721", foM: "#525d2a", foL: "#767f34", flor: "#f3a03d", apag: "#3f4d4a",
  r0: "#dad8c0", R0: "#f0e6c8", r1: "#54827d", R1: "#71a39c", r2: "#9d561c", R2: "#b9732c",
  r3: "#525d2a", R3: "#767f34", r4: "#87a7ab", R4: "#b6cbcd",
  pe: "#4a4535", peM: "#6d6754", peL: "#918a70", peR: "#b3a47f"   // stone, warm and not slate
