// ---------- ONE LIGHTING REGIME ----------
// The decorations, the rocks, the neighbours and the hero all took the hour; the houses, the
// trees, the kitchen stall, the bunting and the rooftops did not, because they were written
// in literal hex — and a literal hex does not know what time it is. The street was lit twice
// in one frame: a bench going dark at midnight next to a house standing in the afternoon.
// Every SURFACE in the world now comes through here, at the same world dose the decorations
// use (floor 0.06, full tint). What stays exempt is what is genuinely EMITTING: a lit window,
// the glass of a lamp, the wet smear under it, and the Cetro. That is the rule the lamps
// already followed, and it is the only rule — a thing is either a source or it takes the hour.
// Resolved on the same 24 steps of the day, so this costs one small object lookup per fill.
let mundoPasso = -1, mundoCor = {}, mundoPal = {};
function wcPasso() {
  const k = horaKey() >> 2;
  if (k !== mundoPasso) { mundoPasso = k; mundoCor = {}; mundoPal = {}; }
  return mundoPasso;
}
function wc(hex) {
  wcPasso();
  let v = mundoCor[hex];
  if (!v) v = mundoCor[hex] = rgbS(luzPersonagem(hexA(hex), 0.06, 1));
  return v;
}
// the same, for a whole sprite palette; the id carries the step so the baked canvas follows
function wp(nome, pal) {
  const id = nome + ":" + wcPasso();
  let v = mundoPal[id];
  if (!v) { v = mundoPal[id] = { _id: id }; for (const c in pal) v[c] = wc(pal[c]); }
  return v;
}
let plantaPal = { K: "#22190d", D: "#3e4721", B: "#525d2a", H: "#767f34" };
// ---- decorations: authored sprite frames now (decor_0..7) ----
// The bench / lamp / plant / planter / chair / washing line were procedural rects; they are
// authored sprites now, blitted HD over the world like the hero. Two new props the slice adds
// — a trash can and strung bunting — get their own helpers. Placement (which prop, where) is
// unchanged in the segment loops; only the picture changed. The lamp keeps its emitted light.
/*DECOR_B64_START — generated by test/inline-sheets.js, do not edit by hand*/
const DECOR_B64 = [
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,",
    "data:image/webp;base64,"
  ];
/*DECOR_B64_END*/
const DECOR_SPR: HTMLImageElement[] = [];
DECOR_B64.forEach(function (d, i) { const im = new Image(); im.src = d; DECOR_SPR[i] = im; });
// 0 bench · 1 lamp · 2 potted plant · 3 planter · 4 chair · 5 washing line · 6 trash · 7 bunting
const DECOR_H_PX = [15, 38, 18, 16, 17, 24, 16, 26];
const decorScale: number[] = [];
function decorBlit(idx, cxc, gy, targetH) {
  const img = DECOR_SPR[idx]; if (!img || !img.complete || !img.naturalWidth) return;
  let sc = decorScale[idx];
  if (!sc) sc = decorScale[idx] = targetH / img.naturalHeight;
  const dw = Math.round(img.naturalWidth * sc), dh = Math.round(img.naturalHeight * sc);
  cx.imageSmoothingEnabled = true;
  cx.drawImage(img, Math.round(cxc - dw / 2), Math.round(gy - dh), dw, dh);
  cx.imageSmoothingEnabled = false;
}
function vaso(x, gy) { sombra(x + 5, gy, 10, 0.16); decorBlit(2, x + 5, gy, DECOR_H_PX[2]); }
function banco(x, gy) { sombra(x + 11, gy, 19, 0.16); decorBlit(0, x + 11, gy, DECOR_H_PX[0]); }
function cadeira(x, gy) { sombra(x + 4, gy, 8, 0.14); decorBlit(4, x + 4, gy, DECOR_H_PX[4]); }
function jardineira(x, gy) { sombra(x + 9, gy, 17, 0.16); decorBlit(3, x + 9, gy, DECOR_H_PX[3]); }
function lixeira(x, gy) { sombra(x + 5, gy, 10, 0.16); decorBlit(6, x + 5, gy, DECOR_H_PX[6]); }
