function drawScene() {
  const h = worldHealth();
  const R = ritmoPasso();           // 0 = GO STEADY, 1 = GO FAST, eased across ~1.1s
  const RQ = ritmoQ();              // the same choice, weighted by what it is costing
  const P = pal(h);                 // the whole world's colour, resolved once per health step
  const smog = 0;                   // tiredness is gone, and it was the only thing that made smog
  // The air in front of a world being pushed thickens BEFORE the team is worn: the old
  // `smog` only ever answered to tiredness, which lags the decision by minutes. Rhythm gets
  // its own share of it so the switch is felt now, and tiredness still stacks on top.
  const smogV = Math.min(0.92, smog + R * 0.26 + R * smog * 0.4);
  // Is an HD painted backdrop live for this scenario? If so, #scene is transparent where the
  // procedural sky/mountains/city/near-scenery would be, and those layers are skipped so the
  // painting behind shows through. The gameplay layer and the health/rhythm weather stay.
  const pintado = fundoPintado();
  // sky, sun and glow: dithered gradient baked once per health step — OR clear to transparent
  if (pintado) cx.clearRect(0, 0, W, H);
  else cx.drawImage(skyCanvas(h), 0, 0);
  // Clouds. They were three flat rectangles of one grey — the crudest thing in the sky and
  // the sky is most of the frame. Now lobes with a sunlit crown and a shaded belly, and the
  // lower they hang the smaller and hazier they get, which puts distance in the sky too.
  const nubB = P.nuvB, nubT = P.nuvT, nubD = P.nuvD;
  // ...and whether there is any cloud at all is the place's, for the same reason the ramp is.
  // Cloud is a fact about the SKY, and MATA ATLÂNTICA's panel has no sky in it — 0.5% of its
  // top fifth and 0.0% of the four below — so a cumulus drifting through a gap in the canopy
  // is not atmosphere, it is a bug you can see. `nuvem: 0` is the whole of that decision, and
  // it is 1 everywhere else, so the street and the square keep their skies to the pixel.
  const nuvemQ = ceuP("nuvem");
  if (nuvemQ && !pintado) {
  // A HIGH STRATUM, above the cumulus. The cumulus sit one every 34 px of screen and there
  // are only four of them across a 130 px frame, all of them in one bank low in the sky, so
  // everything above that bank was bare gradient — and that is 38% of the picture. Every one
  // of the board's four LUZ & ATMOSFERA panels has a full sky: banded cirrus over the
  // cumulus, densest at TARDE. These are streaks, not lobes — long, two or three pixels
  // thick, a lit upper edge, and the slowest parallax in the frame (0.05, half the cumulus)
  // because they are the furthest thing there is. They cannot crowd anything: they live
  // between y8 and y=0.34*GROUND, which is 100 px above the hero's head.
  {
    const passo = 30, vel = 0, teto = GROUND * 0.44;   // cirrus static
    const k0 = Math.floor(worldX * vel / passo) - 1;
    for (let k = k0; k < k0 + Math.ceil(W / passo) + 2; k++) {
      const s1 = hash01(k * 11 + 3);
      if (s1 > 0.88) continue;                              // gaps of open sky
      const sx = Math.round(k * passo - worldX * vel) - Math.round(hash01(k * 19 + 7) * 14);
      const cy = 8 + Math.round(hash01(k * 23 + 2) * (teto - 12));
      const linhas = 2 + Math.floor(hash01(k * 31 + 5) * 3);
      for (let l = 0; l < linhas; l++) {
        const s2 = hash01(k * 47 + l * 9 + 1);
        const lw = 16 + Math.round(s2 * 34), ly = cy + l * 4 + Math.round(s2 * 2);
        const lx = sx + Math.round((s2 - 0.5) * 18);
        // thinner and fainter the lower they hang: the same air that eats the ridges
        const prof = Math.min(1, ly / teto);
        cx.globalAlpha = (0.30 + s2 * 0.24) * (1 - prof * 0.45);
        cx.fillStyle = nubB; cx.fillRect(lx, ly, lw, 2);
        cx.fillStyle = nubD; cx.fillRect(lx + 3, ly + 2, lw - 8, 1);   // the shaded underside
        cx.globalAlpha = (0.34 + s2 * 0.26) * (1 - prof * 0.45);
        cx.fillStyle = nubT; cx.fillRect(lx + 2, ly, lw - 5, 1);       // sun on top: it is above
      }
      cx.globalAlpha = 1;
    }
  }
  // ONE SIZE CLASS IN ONE BANK IS NOT WHAT THE BOARD HAS. Measured, on the RUA DO BAIRRO
  // panel: cloud is 26% of its sky and 4.9% of the picture at a value separation of 49 over
  // the sky behind it, and the widest tenth of its cloud rows is **3.5% of the frame's
  // width** — a loose chain of small crisp puffs at several heights, with one bigger cluster.
  // Ours measured 19% of the sky and 7.1% of the picture at a separation of 45: LESS cloud
  // than the board, in far FEWER and far BIGGER pieces, the widest tenth at **36.9%** of the
  // width. So the separation was never the problem, which is why two waves of pushing the
  // cloud's VALUE around got refused by the screenshot. The size distribution was.
  // Three classes off their own hash — roughly two thirds small, a quarter medium, a tenth
  // the big cluster — on a tighter spacing, so the same painted area arrives as eight or ten
  // pieces instead of four. No new object and no new draw call: same loop, same lobes.
  const passoN = 12;
  const ck0 = Math.floor(0 / passoN) - 1;
  for (let k = ck0; k < ck0 + Math.ceil(W / passoN) + 2; k++) {
    const sx = Math.round(k * passoN - 0) + Math.round((hash01(k * 37 + 2) - 0.5) * 11);
    const prof = hash01(k * 3 + 1);                       // 0 = high overhead, 1 = near the horizon
    const cy = Math.round(H * 0.09 + prof * GROUND * 0.58);
    const cls = hash01(k * 53 + 8);
    const classe = cls > 0.90 ? 52 : cls > 0.66 ? 31 : 17;
    const cs = (1.15 - prof * 0.55) * (0.8 + hash01(k * 9 + 6) * 0.5);
    // A cumulus is the union of a few discs sitting on one flat base, not a stack of
    // rectangles. The top is found per column as the highest disc over that column, which
    // is what gives the bulging crown and the notches between lobes that read as cloud.
    const w0 = Math.max(9, Math.round(classe * cs));
    // ...and one silhouette stamped ten times is a row of polka dots, which is the thing the
    // board's sky is least like. Two lobe sets — one that towers over a narrow shoulder, one
    // that spreads flat — and a vertical stretch on the bulge, so the chain carries tall and
    // flat pieces at the same width instead of one shape at ten sizes.
    const lobos = hash01(k * 61 + 4) > 0.5
      ? [[0.16, 0.10, 0.19], [0.37, -0.10, 0.25], [0.58, 0.03, 0.22],
         [0.78, 0.13, 0.17], [0.47, 0.06, 0.20]]
      : [[0.20, 0.12, 0.17], [0.44, -0.18, 0.21], [0.62, -0.02, 0.24],
         [0.82, 0.14, 0.15], [0.33, 0.05, 0.18]];
    const alt = 0.80 + hash01(k * 71 + 6) * 0.65;
    const topo = new Array(w0 + 1);
    for (let x = 0; x <= w0; x++) {
      let t2 = cy;
      for (let l = 0; l < lobos.length; l++) {
        const lx = lobos[l][0] * w0, lr = lobos[l][2] * w0, d = Math.abs(x - lx);
        if (d < lr) t2 = Math.min(t2, cy + (lobos[l][1] * w0 - Math.sqrt(lr * lr - d * d)) * alt);
      }
      topo[x] = Math.round(t2);
    }
    cx.globalAlpha = 0.88 - prof * 0.36;                  // haze eats the far ones
    let ini = 0;
    for (let x = 1; x <= w0; x++) {                       // the mass, runs of equal height
      if (x === w0 || topo[x] !== topo[ini]) {
        if (topo[ini] < cy) {
          cx.fillStyle = nubB; cx.fillRect(sx + ini, topo[ini], x - ini, cy - topo[ini] + 1);
          cx.fillStyle = nubT; cx.fillRect(sx + ini, topo[ini], x - ini, 2);   // sunlit crown
        }
        ini = x;
      }
    }
    cx.fillStyle = nubD;                                  // the belly it sits on
    cx.fillRect(sx + Math.round(w0 * 0.06), cy - 1, Math.round(w0 * 0.88), 2);
    cx.fillStyle = nubB;                                  // a wisp trailing off downwind
    cx.fillRect(sx + w0, cy - 3, Math.round(w0 * 0.22), 2);
    cx.globalAlpha = 1;
  }
  }
  // THE PLACE, DRAWN. Everything from here to the wires is the scenario's, not the
  // street's: `A` is the frame's resolved state (health, palette, rhythm, smoke) and each
  // hook is one layer of the picture. RUA DO BAIRRO is scenario #1 and its hooks hold the
  // nineteen waves of measured drawing that used to live inline here.
  const A = { h: h, P: P, R: R, RQ: RQ, smog: smog, smogV: smogV };
  const C = CEN();
  // On a painted scenario every one of these is already in the painting (sky, ridges, town,
  // ground, decor, NPCs, wires), so drawing them would double up. Skip them all; the painting
  // is the backdrop, and only the gameplay + weather run below.
  // Os sete `!` abaixo não são descuido: NENHUM cenário declara estes ganchos hoje. Eles foram
  // apagados na faxina de 2026-08-04 junto com as 1.947 linhas de desenho procedural, e este
  // ramo só roda se `fundoPintado()` for falso — o que exigiria uma das seis pinturas sumir do
  // arquivo. O `!` mantém o comportamento EXATO de hoje (estouraria, se chegasse aqui) em vez de
  // trocá-lo por um `?.` que engoliria a falta em silêncio. Está no relatório da migração.
  if (!pintado) {
    C.fundo!(A);
    C.meio!(A);
    C.veg!(A);
    C.chao!(A);
    C.segmentos!(A);
    C.moldura!(A);
    C.fios!(A);
  }

  // owner: sprouts removed with the rest of what fired alongside the strike.

  // owner: the smog bands and the low bank on the horizon are gone — no more grey drifting
  // across the top of the picture.

  // owner: birds, ash, cinders, leaves, motes, the rhythm gust and the butterflies are
  // all gone — the owner wanted the extra particles off the screen.

  // owner: the shockwave field is gone with the slam that made it.

  desenharFolhas();

  // monsters of pollution and greed roam ahead
  drawMobs(smog);

  // THE SPARK — running hero
  drawHero();
  desenharMagias();

  // particles (sparks, ash, leaves)
  for (let i = parts.length - 1; i >= 0; i--) {
    const p = parts[i];
    p.vy += (p.grav || 0) / 60;
    p.x += p.vx / 60; p.y += p.vy / 60; p.life -= 1 / 60;
    if (p.life <= 0 || p.y > H || p.x < -6) { parts.splice(i, 1); continue; }
    const pa = Math.min(1, p.life * 2), px2 = Math.round(p.x), py2 = Math.round(p.y);
    if (false) {                                   // owner: no halos left to draw
      cx.globalAlpha = pa * 0.26; cx.fillStyle = p.aura!;   // ramo morto: nada escreve `aura`
      cx.fillRect(px2 - 2, py2 - 1, 6, 4); cx.fillRect(px2 - 1, py2 - 2, 4, 6);
    }
    cx.globalAlpha = pa;
    // Ambient weather is made of THINGS — ash, cinders, blown leaves, petals — so it takes
    // the hour like everything else in the street. Combat sparks and the motes of channelled
    // light do not: those are the magic, and the direction says the magic never dims with the
    // world. Before this, a night frame had bright green and pink confetti falling through it.
    cx.fillStyle = p.amb ? wc(p.c) : p.c;
    cx.fillRect(px2, py2, 2, 2);
    cx.globalAlpha = 1;
  }

  // Floating numbers. At 1 world px = 3 screen px a 5x7 glyph at scale 2 covered the hero,
  // so the world text is drawn at scale 1 now: 15x21 screen px, still crisp, no longer a sign.
  floats.forEach(function (f) {
    cx.globalAlpha = Math.min(1, f.life / 20);
    texto(f.txt, f.x, f.y - 12, 1, f.txt.charAt(0) === "+" ? "#ffe488" : "#fdf6e6", "#12242e");
    cx.globalAlpha = 1;
    f.y -= 0.7; f.life--;
  });
  floats = floats.filter(function (f) { return f.life > 0; });

  // FOREGROUND: fast dark silhouettes just below the path (real depth). The old version was
  // a row of identical blocks with a hard straight top — a picket fence. Same idea, but the
  // edge is now broken up by clumps and blades of varying height, and the very top catches
  // a thread of light so the band reads as grass close to the camera, not as a black bar.
  // ...but not on a painted scenario: the painting already carries its own near ground and
  // foliage, so this procedural grass band would double up over it. Drop it there.
  if (!pintado) {
  const fgC = P.frenteC, fgL = P.frenteL;
  const fgTop = Math.min(H - 8, GROUND + 20);
  const fk0 = Math.floor(worldX * 1.45 / 34) - 1;
  for (let k = fk0; k < fk0 + Math.ceil(W / 34) + 2; k++) {
    const sx = Math.round(k * 34 - worldX * 1.45);
    const fy = fgTop + Math.floor(hash01(k * 37 + 5) * 5);
    cx.fillStyle = fgC;
    cx.fillRect(sx, fy, 34, H - fy);
    for (let c = 0; c < 4; c++) {                 // rounded clumps breaking the skyline
      const cw = 5 + Math.floor(hash01(k * 17 + c * 3 + 1) * 8);
      const ch2 = 2 + Math.floor(hash01(k * 29 + c * 5 + 2) * 5);
      const cx2 = sx + Math.floor(hash01(k * 13 + c * 7 + 3) * (34 - cw));
      cx.fillRect(cx2, fy - ch2, cw, ch2 + 2);
      cx.fillStyle = fgL; cx.fillRect(cx2 + 1, fy - ch2, cw - 2, 1);
      cx.fillStyle = fgC;
    }
    for (let b = 0; b < 6; b++) {                 // blades poking up out of the clumps
      const bx2 = sx + Math.floor(hash01(k * 43 + b * 11 + 4) * 32);
      const bh2 = 3 + Math.floor(hash01(k * 59 + b * 13 + 5) * 6);
      cx.fillRect(bx2, fy - bh2 - 2, 1, bh2 + 3);
    }
  }
  }

  // No final pass. There used to be an 'overlay' grade and a dithered vignette here, and
  // a CSS vignette and scanlines on top of those. Direction C is clean by choice: the look
  // has to come out of value architecture and chroma, and every one of those four layers
  // was quietly pulling the frame back toward the mud they were meant to fix.
}

// ---------- things you can put a thumb on ----------
// Drawn after drawScene() on purpose: an affordance has to stay legible, so it sits on
// top of the colour grade instead of inside it. Sprites are not touched here — these are
// markers over the world, not monsters.
// A trouble's remaining hits, drawn over its head. Pure function of `m.hp` / `m.hpMax`,
// no DOM, one keyline plus n little blocks — cheap enough to run for every mob every frame.
// ESTÉTICA: this whole readout is one function on purpose. The state it needs is `m.hp`,
// `m.hpMax`, `m.type`, `m.flash` and `m.dying`; restyle or replace the body freely.
const VIDA_TOPO = { smog: 30, barrel: 27, cash: 21 };   // world px above ground per sprite
// THE READOUT AND THE HOUR. This is game signal, not scenery, so it does NOT take the
// hour's TINT — a pip that goes blue at midnight has joined the world it is supposed to
// sit on top of. But it cannot ignore the frame's LEVEL either. Once the monsters were
// floored at 0.26 for the night, the untouched #e8edf6 pips became the brightest thing in
// the whole ground band: measured, 183 px over luma 200 against 78 px for everything else
// in a NOITE frame, peaking at 237 — above the Cetro's resting hub (195.6) and above the
// crystal (214.7), which inverts the one rule the lighting wave set.
// So they dim in VALUE only, neutral, on a high floor. At NOITE the full pip goes 236 ->
// 158: still ~90 luma over a night street whose 99.5th percentile is 124, still boxed in
// its own dark keyline, and now below the light source instead of above it. The hit flash
// keeps a higher floor because two frames of white is the confirmation that you connected.
// Empty pips take the same factor as full ones, so the read "how much is left" is untouched.
// A PLAIN RED HEALTH BAR, WHICH IS WHAT EVERY GAME HAS. The readout was a row of white pips
// — one block per hit point, blocks going out one at a time — and the owner named the two
// things wrong with it in one line: *"a vida dos bichinhos parece que são pontinhos brancos,
// pode ser uma barrinha vermelha padrão em vez de ser blocada, ela vai diminuindo."* It did
// not read as health, and it was white.
//
// The white was already a known defect with a number on it: floored at 0.26 for the night,
// the untouched #e8edf6 pips were the brightest thing in the whole ground band — measured at
// 183 px over luma 200 in a NOITE frame against 78 for everything else, peaking at 237, which
// is ABOVE the Cetro's resting hub (195.6) and above its crystal (214.7) and inverts the one
// rule the lighting wave set. Dimming them was a patch on the symptom. A red fill on a dark
// track fixes it at the root, because the board's own ACENTO reds sit around L 90 — a bar can
// be unmistakable without being the light source in the frame.
//
// It still takes the hour the same way, in VALUE only and on a floor: this is game signal, so
// it must not take the hour's TINT (a bar that goes blue at midnight has joined the world it
// is supposed to sit on top of), and it must not glow at midnight either.
// It reads `m.hp` and `m.hpMax` and nothing else — no hp value, no spawn, no block changes.
const PIP_PISO = 0.67, PIP_PISO_FLASH = 0.82;
// A barra ENCHE, e essa é a conversão inteira do verbo em uma decisão de cor.
//
// Ela drenava de vermelho-sangue para vermelho-escuro: vocabulário de matar. Uma barra que
// esvazia diz "estou destruindo isto"; a mesma barra enchendo diz "estou terminando isto".
// Mesmo número de toques, mesma mecânica, leitura oposta — e é a leitura que o jogo existe
// para dizer. O verde é o do resto da paleta, não uma cor nova.
let pipPasso = -1, FEITO_CHEIO = "#38b764", FEITO_QUASE = "#6fdd94", FEITO_LUZ = "#b5e08c",
    FEITO_TRILHO = "#22303a", PIP_FLASH = "#ffffff";
function pipLuzPasso() {
  const k = horaKey() >> 2;                        // same 24 steps a day as everything else
  if (k === pipPasso) return;
  pipPasso = k;
  const e = escuridao();
  const dim = function (hex, piso) {
    const c = hexA(hex), f = 1 - (1 - piso) * e;
    return rgbS([cl255(c[0] * f), cl255(c[1] * f), cl255(c[2] * f)]);
  };
  FEITO_CHEIO = dim("#38b764", PIP_PISO);
  FEITO_QUASE = dim("#6fdd94", PIP_PISO);          // o último terço clareia, não escurece
  FEITO_LUZ = dim("#b5e08c", PIP_PISO);            // uma fileira acesa no topo do preenchido
  FEITO_TRILHO = dim("#22303a", PIP_PISO);
  PIP_FLASH = dim("#ffffff", PIP_PISO_FLASH);
}
function desenharVidaMob(m) {
  if (m.dying > 0 || !m.hpMax) return;
  const sx = Math.round(m.wx - worldX);
  if (sx < -20 || sx > W + 20) return;
  pipLuzPasso();
  // one width for every monster, so "half a bar" means the same thing whatever you are
  // looking at — with pips the bar's LENGTH was the monster's max hp, which read as "this one
  // is wider" rather than as "this one takes more hits"
  const larg = 20, alt = 3;
  const x0 = sx + 5 - (larg >> 1), y = GROUND - (VIDA_TOPO[m.type] || 22);
  // `m.hp` continua sendo quantos alcances faltam — o nome interno é herdado e trocá-lo em
  // trinta lugares não mudaria um pixel. O que mudou é o que a barra MOSTRA: a fração já
  // FEITA, não a que resta.
  const frac = Math.max(0, Math.min(1, 1 - m.hp / m.hpMax));
  const cheio = Math.round(larg * frac);
  cx.fillStyle = "#10121c";                       // contorno: tem que ler sobre qualquer chão
  cx.fillRect(x0 - 1, y - 1, larg + 2, alt + 2);
  cx.fillStyle = FEITO_TRILHO;                    // o trilho vazio que ela vai preenchendo
  cx.fillRect(x0, y, larg, alt);
  if (cheio > 0) {
    cx.fillStyle = m.flash > 0 ? PIP_FLASH : (frac >= 0.66 ? FEITO_QUASE : FEITO_CHEIO);
    cx.fillRect(x0, y, cheio, alt);
    if (m.flash <= 0) { cx.fillStyle = FEITO_LUZ; cx.fillRect(x0, y, cheio, 1); }
  }
}

// THE SUPER, on screen. Placeholder spectacle: a wall of light leaving the hero and
// crossing the whole frame, a bright horizon line, and the road lit from underneath while
// the window lasts. It is deliberately one self-contained function reading one object —
// ESTÉTICA: replace the body, keep the contract (`superFx = { t, dur, sx }`, `superT`).
// owner: desenharSuper() removed — only the strike is left.

function desenharMundo() {
  const pulso = 0.6 + 0.4 * Math.sin(animT * 6);
  // what a beaten trouble left behind, waiting for a thumb
  drops.forEach(function (d) {
    const sx = Math.round(d.wx - worldX);
    if (sx < -12 || sx > W + 12) return;
    const y = GROUND - 16 + Math.round(Math.sin(animT * 5 + d.wx * 0.1) * 2);
    const fim = Math.max(0, Math.min(1, (CFG.dropVida - d.t) / 2));
    // the tick colour still says which trouble left it; the authored item says what it gives you
    const cor = d.type === "cash" ? "#f3a03d" : d.type === "barrel" ? "#71a39c" : "#f2d2dc";
    cx.globalAlpha = fim;
    const dimg = dropDe(d.type);
    if (dimg && dimg.complete && dimg.naturalWidth) {
      const dsc = dropScaleFor(dimg);
      const ddw = Math.round(dimg.naturalWidth * dsc), ddh = Math.round(dimg.naturalHeight * dsc);
      cx.imageSmoothingEnabled = true;                 // centred on the old icon's footprint so
      cx.drawImage(dimg, Math.round(sx + 2 - ddw / 2), Math.round(y + 10 - ddh), ddw, ddh);
      cx.imageSmoothingEnabled = false;                // the pickup + and ticks still frame it
    }
    // ...and a small plus beside it, so it reads as a PICKUP and not as scenery: the world is
    // already full of leaves and this is the only one you can take
    // ...in the board's ACENTO gold and NOT in the chrome's cream: #fdf6e6 measures L 244,
    // which would put a pickup above the Cetro's hub (195.6) and its crystal (214.7) in a
    // night frame, and the Cetro being the brightest warm thing after dark is a rule this
    // file has held since the lighting wave. #eba748 is L 175 and unmistakably a plus.
    cx.fillStyle = "#12242e";
    cx.fillRect(sx + 6, y - 2, 5, 5);
    cx.fillStyle = "#eba748";
    cx.fillRect(sx + 8, y - 1, 1, 3); cx.fillRect(sx + 7, y, 3, 1);
    // four ticks breathing around it: pixel-art for "pick me up"
    cx.globalAlpha = fim * pulso;
    cx.fillStyle = cor;
    const r = 6 + Math.round(pulso * 2);
    cx.fillRect(sx + 1, y - r, 1, 3); cx.fillRect(sx + 1, y + 6 + r - 3, 1, 3);
    cx.fillRect(sx - 3 - r, y + 3, 3, 1); cx.fillRect(sx + 5 + r - 3, y + 3, 3, 1);
    cx.globalAlpha = 1;
  });
  // how much of a trouble is left, over its head. Damage was already in the game — hits
  // came off `hp` — but nothing ever showed it, so it read as if nothing was happening
  // until the thing suddenly popped. It was pips for a while, on the argument that at two to
  // five hits you can count them; the owner wanted the thing every game has and he was right
  // twice over — see `desenharVidaMob`.
  mobs.forEach(function (m) { desenharVidaMob(m); });
  // QUEM ESTÁ ESPERANDO. Aqui havia dois tiques VERMELHOS piscando nos pés, e vermelho
  // piscando é a gramática de perigo e de erro — a gramática errada. No capítulo 2 quem chega
  // e espera é gente, e o §2.2 não admite que o jogo desenhe uma barra de aflição em cima
  // dela. Então o sinal é o contrário disso: dois anéis mornos no chão, respirando devagar,
  // do tamanho de um lugar reservado. Não é contagem regressiva — não encolhe, não muda de
  // cor, não fica vermelho perto do fim. Diz "tem alguém aqui", e só. O que o tempo faz é
  // apagar a luz nos últimos instantes, o que é uma despedida e não um alarme.
  mobs.forEach(function (m) {
    if (!m.parado || m.dying > 0) return;
    const sx = Math.round(m.wx - worldX) + 5;
    // respiração lenta e igual para todas: uma rua onde cada lugar pisca no seu ritmo lê como
    // ruído. `m.wx` entra na fase só para as auras não baterem em uníssono.
    const resp = 0.5 + 0.5 * Math.sin(animT * 2.1 + m.wx * 0.02);
    // e some nos últimos 0,6 s de espera — a única coisa que o relógio muda na tela
    const saindo = Math.max(0, Math.min(1, m.espera / 0.6));
    cx.save();
    // um lugar de luz no chão, e depois o contorno dele. Só o anel, a 1 px numa tela de 160
    // px de mundo, sumia contra a terra pintada — medido olhando o print, que é o que o
    // CLAUDE.md manda fazer e o teste não faz.
    cx.fillStyle = "#f3dda6"; cx.strokeStyle = "#fbeec4"; cx.lineWidth = 2;
    const base = (0.55 + 0.45 * resp) * saindo;
    const r0 = 15 + resp * 2;
    cx.globalAlpha = 0.17 * base;
    cx.beginPath(); cx.ellipse(sx, GROUND + 1, r0, r0 * 0.32, 0, 0, 6.283); cx.fill();
    for (let a = 0; a < 2; a++) {
      const r = r0 + a * 6;
      cx.globalAlpha = (0.46 - a * 0.22) * base;
      cx.beginPath(); cx.ellipse(sx, GROUND + 1, r, Math.max(1, r * 0.32), 0, 0, 6.283); cx.stroke();
    }
    cx.restore();
    cx.globalAlpha = 1;
  });
}

// ---------- HUD ----------
// O `!` está aqui e não nas ~90 chamadas: todo id que passa por `$` é escrito à mão no mesmo
// arquivo, e o único jeito de ele não existir é alguém apagar a marcação sem apagar o código —
// caso em que o erro tem que ser alto no primeiro uso, e é.
const $ = (id: string) => document.getElementById(id)!;
function fmt(n) {
  if (n >= 1e9) return (n / 1e9).toFixed(3) + "B";
  if (n >= 1e6) return (n / 1e6).toFixed(3) + "M";
  if (n >= 1e4) return (n / 1e3).toFixed(1) + "K";
  return Math.floor(n).toLocaleString("pt-BR");
}
function desenhar() {
  verificarCenario();
  $("energia").textContent = fmt(S.energia);
  $("nFlor").textContent = String(S.recursos.flor | 0);
  // a leitura de progresso: em que época você está e quanto falta para virar
  const pc = Math.floor(progressoCena() * 100);
  // Sem a porcentagem em texto: ela ficou redundante com a barra logo abaixo, e duas leituras
  // da mesma coisa competindo pelo mesmo espaço é pior que uma boa. E não é mais "ÉPOCA 3" —
  // um capítulo com nome diz onde você está; um capítulo com número diz só quantos faltam.
  $("rotuloEpoca").textContent = EPOCAS[epocaAtual()].nome;
  $("barraEpocaFill").style.width = pc + "%";
  $("nAgua").textContent = String(S.recursos.agua | 0);
  $("nRef").textContent = String(S.recursos.refeicao | 0);
  pintarIconesDrop();
  $("ganhoClique").textContent = ganhoClique().toFixed(1);

  // the rhythm card: icon, name and colour follow S.modo. This used to live in
  // desenharRitmo(), inside the projects panel that is gone.
  const rapido = S.modo === "carvao";
  $("modeNome").textContent = rapido ? "CORRER" : "ANDAR";
  $("modeQuick").className = "cartao " + (rapido ? "fast" : "steady");
  // O ícone do ritmo é FIXO — um pé, o mesmo nos dois modos — e é pintado uma vez pelo
  // `pintarIconesDrop()`. Quem diz qual ritmo está valendo são o nome e a cor do cartão, que
  // mudam logo acima; a chama e a folha eram duas leituras da mesma coisa.

  // the one card left that carries a number of its own
  // owner: no note under the card — the button glows when something is affordable, that is all
  const podeComprar = [1, 2, 3, 4].filter(function (n) {
    return !S["u" + n] && S.energia >= CFG["custoU" + n];
  }).length;
  // toggle, never reassign: reassigning wiped the class that turns this card into the
  // panel's close button
  $("openUpgrades").classList.toggle("pronto", podeComprar > 0);



  [1, 2, 3, 4].forEach(function (n) {
    const custo = CFG["custoU" + n], comprado = S["u" + n];
    $("cardU" + n).classList.toggle("comprado", comprado);
    $("btnU" + n).textContent = comprado ? "✓" : (custo === 0 ? "GRÁTIS" : fmt(custo));
    ($("btnU" + n) as HTMLButtonElement).disabled = comprado || S.energia < custo;
  });

  alertaMundo();
}

// The super's charge, on the button that will spend it: one square per completed combo,
// built from CFG so the count cannot drift from the mechanic.
// owner: desenharSuperHUD() removed — only the strike is left.

// A project is the thing that earns while you are not touching the screen, and the sheet
// used to show its price and nothing else. Two short lines: what you already have, and
// what one more buys — both read off the live formulas.
// owner: desenharProjetos() removed with its panel.

// The skills surface. One skill ships; the sheet is a list, so a second one is markup and
// a CFG line — but there are no empty slots pretending to be content.
// owner: desenharSkills() removed with the AUTO-FIRE skill.

// Everything the player needs to make the one decision this prototype measures.
// Every number is read from the live formulas; none of it is written down twice.
// owner: desenharRitmo() removed with its panel. The rhythm card in the control block still renders itself.

// owner: the top alert strip is gone (element, style and text). Kept as an empty function
// because the frame loop and several state changes still call it.
// ZERAR — interruptor de teste, irmão do u4 e com o mesmo vermelho.
//
// Duas decisões:
//
// 1. NÃO usa confirm(). Diálogo do navegador no meio de um jogo em tela cheia quebra a
//    imersão e, no celular, aparece fora do lugar. O confirme é DOIS TOQUES no próprio
//    botão: o primeiro pergunta, o segundo apaga, e a pergunta expira em 4s sozinha. Sem
//    isso, um toque distraído apaga a partida de alguém.
// 2. Zera pelo ESQUEMA, não por localStorage.clear(). Escrever os padrões e salvar é o
//    caminho que já passa pela validação; limpar o storage na mão deixaria o estado em
//    memória vivo e o próximo autosave regravaria tudo de volta — que foi exatamente o que
//    aconteceu quando tentei zerar pelo console.
let zerarArmado = 0;
function zerarJogo() {
  const agora = Date.now();
  const b = $("btnU5");
  if (agora - zerarArmado > 4000) {          // primeiro toque: pergunta
    zerarArmado = agora;
    if (b) b.textContent = "tem certeza?";
    setTimeout(function () { if (b && Date.now() - zerarArmado >= 4000) b.textContent = "apagar"; }, 4100);
    return;
  }
  zerarArmado = 0;                            // segundo toque: apaga
  S.energia = 0; S.energiaTotal = 0; S.cenario = 0;
  S.u1 = S.u2 = S.u3 = S.u4 = false;
  S.modo = "limpo";
  S.recursos = { flor: 0, agua: 0, refeicao: 0 };
  S.cuidado = 1; cuidadoVisto = 1;
  worldX = 0; mobs.length = 0; drops.length = 0; floats.length = 0;
  salvar();
  try { localStorage.removeItem(CHAVE_RET); } catch (e) {}
  R = { dias: [], segundos: 0, tochas: 0 };
  if (b) b.textContent = "apagado";
  redesenharFundo();
  desenhar();
  setTimeout(function () { if (b) b.textContent = "apagar"; }, 1500);
}

function alertaMundo() {}

function anunciar(txt, tom) {
  // owner: remove center-screen announcements. Neutered: never applies the .mostra class,
  // so the #anuncio element stays in the DOM but never becomes visible. Everyone else can
  // still call this; it just does nothing.
}
