function semearAnuncios() {          // adopt the current state without shouting, so a reload
  anChamada = !!chamada;             // or an offline jump does not fire a burst on the first frame
  anMutirao = mutiraoT > 0;
  anTocha = S.energiaTotal >= CFG.metaPrestigio;
}
